"""Generate portable static pages from the editable business content."""
import json,html,re,shutil
from pathlib import Path
from PIL import Image,ImageOps

ROOT=Path(__file__).parent
DIST=ROOT/'dist'
DATA=json.loads((ROOT/'site-content.json').read_text(encoding='utf-8'))
B=DATA['business'];SERVICES=DATA['services'];PROJECTS=DATA['projects']
ORIGIN='https://montesinos-electric-redesign.wescuder.chatgpt.site'
e=lambda s:html.escape(str(s),quote=True)

ICONS={
 'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 'phone':'<path d="M7 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a15 15 0 0 1-7-7l2-2-2-5Z"/>',
 'pin':'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 'check':'<path d="m5 12 4 4 10-10"/>',
 'shield':'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 'people':'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v2"/>',
 'bolt':'<path d="m13 2-9 12h7l-1 8L21 9h-8l1-7Z"/>',
 'quote':'<path d="M4 4h16v13H9l-5 4V4Z"/><path d="M8 9h8m-8 4h5"/>',
 'expand':'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>'
}
def icon(name):return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>'
def button(label,href,style=''):return f'<a class="button {style}" href="{e(href)}">{label}{icon("arrow")}</a>'
def textlink(label,href):return f'<a class="text-link" href="{e(href)}">{label}{icon("arrow")}</a>'
def image(file,alt,cls='',eager=False):
    source=DIST/'assets'/file
    webp=source.with_suffix('.webp')
    return f'<img src="/assets/{e(webp.name)}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'

# Preserve originals outside the deployment and serve compressed copies.
originals=ROOT/'source-assets';originals.mkdir(exist_ok=True)
for source in list((DIST/'assets').glob('b491a5*')):
    if source.suffix=='.webp':continue
    shutil.copy2(source,originals/source.name)
    with Image.open(source) as photo:
        photo=ImageOps.exif_transpose(photo).convert('RGB');photo.thumbnail((1800,1800))
        photo.save(source.with_suffix('.webp'),'WEBP',quality=84,method=6)
    source.unlink()
for source in originals.glob('b491a5*'):
    dest=DIST/'assets'/source.with_suffix('.webp').name
    if dest.exists():continue
    with Image.open(source) as photo:
        photo=ImageOps.exif_transpose(photo).convert('RGB');photo.thumbnail((1800,1800));photo.save(dest,'WEBP',quality=84,method=6)
logo=(ROOT/'logo-source.svg').read_text(encoding='utf-8')
logo=re.sub(r'<defs>.*?</defs>','',logo,flags=re.S).replace('viewbox=','viewBox=').replace('preserveaspectratio="none"','preserveAspectRatio="xMidYMid meet"').replace('fill="#FFB39E"','fill="#000000"')
(DIST/'assets'/'logo.svg').write_text(logo,encoding='utf-8')

def brand():return '<a class="brand" href="/" aria-label="Montesinos Electric home"><img src="/assets/logo.svg" alt="" width="35" height="40"><strong>MONTESINOS<span>ELECTRIC</span></strong></a>'
NAV=[('Services','/services/'),('Our work','/portfolio/'),('Our story','/about/'),('Blog','/blog/')]
def header(active):
    links=''.join(f'<a href="{path}"'+(' aria-current="page"' if path==active else '')+f'>{label}</a>' for label,path in NAV)
    return f'''<a class="skip" href="#main">Skip to content</a><div class="utility"><div class="wrap"><span class="local-line">Family-owned electrical service in Phoenix, Arizona</span><a href="tel:{B['phoneLink']}">Hablamos español &nbsp; {B['phone']}</a></div></div><header class="header"><nav class="nav wrap" aria-label="Main navigation">{brand()}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><div class="navlinks" id="navigation">{links}<a href="/contact/">Contact</a>{button('Get a free quote','/contact/')}</div></nav></header>'''
def footer():
    return f'''<footer class="footer"><div class="wrap"><div class="footer-top"><div>{brand()}<p>Family-owned electrical services. Honest work and the good guy price.</p></div><div><h3>Explore</h3><ul><li><a href="/services/">Our services</a></li><li><a href="/portfolio/">Our work</a></li><li><a href="/about/">Our story</a></li><li><a href="/blog/">Blog</a></li></ul></div><div><h3>How we can help</h3><ul><li><a href="/services/ground-up-service/">Ground-up service</a></li><li><a href="/services/electrical-fixture-installation/">Fixture installation</a></li><li><a href="/services/electrical-troubleshooting/">Troubleshooting</a></li><li><a href="/service-area/">Phoenix service area</a></li></ul></div><div><h3>Let’s talk about your project</h3><a class="phone" href="tel:{B['phoneLink']}">{B['phone']}</a><p>Hablamos español<br>Phoenix, Arizona</p><ul><li><a href="/contact/">Get a free quote</a></li><li><a href="{B['mapsUrl']}" target="_blank" rel="noopener noreferrer">Find us on Google Maps</a></li></ul></div></div><div class="footer-bottom"><span>© 2026 Montesinos Electric. All rights reserved.</span><div><a href="/privacy/">Website privacy</a><a href="/accessibility/">Accessibility</a></div></div></div></footer><div class="mobile-contact"> <a href="tel:{B['phoneLink']}">{icon('phone')}Call Montesinos</a><a href="/contact/">Free quote {icon('arrow')}</a></div>'''
def cta():return f'''<section class="cta"><div class="wrap"><div><h2>Let’s get your project wired.</h2><p>Tell us what you have in mind. Start with a free quote.</p></div><div class="cta-actions">{button('Get a free quote','/contact/')}{button(B['phone'],'tel:'+B['phoneLink'],'outline')}</div></div></section>'''
def lightbox():return '<dialog class="lightbox" aria-labelledby="photo-title"><div class="lightbox-header"><h2 id="photo-title"></h2><button class="lightbox-close" aria-label="Close photo">✕</button></div><img class="lightbox-image" alt=""><div class="lightbox-controls"><button class="lightbox-prev" aria-label="Previous photo">‹</button><span class="lightbox-count" aria-live="polite"></span><button class="lightbox-next" aria-label="Next photo">›</button></div></dialog>'
def project(p):
    src='/assets/'+Path(p['image']).with_suffix('.webp').name
    return f'''<article class="project-card" data-category="{p['category']}"><button class="project-open" data-image="{src}" data-title="{e(p['title'])}" data-category="{p['category']}" aria-label="View photo: {e(p['title'])}"><div class="project-image">{image(p['image'],p['title'])}<span class="project-expand">{icon('expand')}</span></div><div class="project-meta"><span>{p['category']}</span><h3>{e(p['title'])}</h3></div></button></article>'''
def service(s):return f'''<article class="service-card"><a href="/services/{s['slug']}/" aria-label="Learn about {s['name']}">{image(s['image'],s['name']+' by Montesinos Electric')}</a><div class="service-body"><h3><a href="/services/{s['slug']}/">{s['name']}</a></h3><p>{s['short']}</p><div class="service-bottom"><strong>Free quote</strong><a href="/services/{s['slug']}/">Explore service {icon('arrow')}</a></div></div></article>'''
POSTS=[('residential','Residential','From new construction to the finishing touches.','Panels, utility connections, lighting, fans, and outlet wiring for homes.'),('commercial','Commercial','Electrical work that keeps business moving.','Lighting, car wash equipment, panels, and conduit for commercial spaces.'),('industrial','Industrial','Powering the equipment behind the work.','Three-phase motors, compressors, switches, and conduit installations.')]
def blogcard(post):
    slug,category,title,desc=post
    representative={'Residential':PROJECTS[0],'Commercial':PROJECTS[7],'Industrial':PROJECTS[13]}[category]
    return f'''<article class="blog-card"><a href="/post/{slug}/" aria-label="Read {category} project story">{image(representative['image'],representative['title'])}</a><div class="post-meta"><span>{category}</span><time datetime="2025-10-29">Oct 29, 2025</time></div><h3><a href="/post/{slug}/">{title}</a></h3><p>{desc}</p>{textlink('Read project story','/post/'+slug+'/')}</article>'''
def mapblock():return f'''<div class="map-panel"><div class="map-preview">{icon('pin')}<strong>Phoenix, Arizona</strong><span>Let’s talk about your project location.</span><button class="load-map">Load area map</button><small>Area illustration. Load Google Maps to explore.</small></div></div>'''
def area():return f'''<section class="section area"><div class="wrap area-grid"><div class="area-copy"><h2>Local roots.<br>Phoenix connections.</h2><p>Electrical work for homes, businesses, and industrial spaces in the Phoenix area. Give us a call to discuss your location and what your project needs.</p><div class="area-details">{icon('pin')}<div><strong>Phoenix, Arizona</strong><p>Call to confirm availability for your address.</p></div></div>{textlink('Explore our service area','/service-area/')}</div>{mapblock()}</div></section>'''
def story():return f'''<section class="section"><div class="wrap story-grid"><div class="story-photos">{image('b491a5_c102ea168a4c4b76956029cafde38851~mv2.jpg','Montesinos Electric team installing lighting','large')}{image('b491a5_34c9b999e8984462b71b9c1979b3d321~mv2.jpeg','Montesinos Electric crew working on utility piping','small')}</div><div class="story-copy"><span class="story-pill">Family owned</span><h2>Good people.<br>Good electrical work.</h2><p>{B['story']}</p><div class="story-values"><span>{icon('check')}Honest pricing</span><span>{icon('check')}Clear communication</span></div>{textlink('Meet Montesinos Electric','/about/')}</div></div></section>'''
def intro(title,copy,crumb=''):
    return f'<section class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a><span>/</span>{crumb or e(title)}</div><h1>{title}</h1><p>{copy}</p></div></section>'
PAGES={}
def save(path,title,description,content,active='',schema=None):
    url=ORIGIN+path
    business={'@context':'https://schema.org','@type':'Electrician','@id':ORIGIN+'/#business','name':B['name'],'url':ORIGIN+'/', 'telephone':B['phoneLink'],'logo':ORIGIN+'/assets/logo.svg','image':ORIGIN+'/assets/b491a5_b2b366b4313b44678b6aafe6c2ce8d3c~mv2.webp','description':'Family-owned electrical installation, troubleshooting, and maintenance in the Phoenix area.','areaServed':{'@type':'City','name':'Phoenix'},'sameAs':[B['mapsUrl']]}
    ld=[business]+([schema] if schema else [])
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Montesinos Electric</title><meta name="description" content="{e(description)}"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)} | Montesinos Electric"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/b491a5_b2b366b4313b44678b6aafe6c2ce8d3c~mv2.webp"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#ffe13b"><link rel="icon" href="/assets/logo.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False)}</script><script defer src="/app.js"></script></head><body>{header(active)}<main id="main">{content}</main>{footer()}{lightbox()}</body></html>'''
    destination=DIST/path.strip('/')/'index.html' if path!='/' else DIST/'index.html'
    destination.parent.mkdir(parents=True,exist_ok=True);destination.write_text(doc,encoding='utf-8');PAGES[path]=title

home=f'''<section class="hero wrap"><div class="hero-copy"><div class="location">{icon('pin')}Your local Phoenix electricians</div><h1>The good<br>guy price.</h1><p class="intro">Quality electrical work. Honest pricing. A family-owned team for your home, business, and everything you’re building.</p><div class="hero-actions">{button('Get a free quote','/contact/')}<a class="call-link" href="tel:{B['phoneLink']}">{icon('phone')}{B['phone']}</a></div><div class="hero-note">{icon('check')}Residential, commercial & industrial</div></div><div class="hero-photo">{image('b491a5_b2b366b4313b44678b6aafe6c2ce8d3c~mv2.jpg','Finished ceiling lighting and fan installation by Montesinos Electric',eager=True)}<span class="photo-tag">Real work. Montesinos Electric.</span><div class="photo-badge">{icon('people')}<div><strong>Family owned. Built on trust.</strong><small>Nearly 20 years of electrical experience</small></div></div></div></section><div class="trustbar"><div class="wrap trust-items"><div>{icon('shield')}Licensed & insured</div><div>{icon('people')}Family owned & operated</div><div>{icon('quote')}Free project quotes</div><div>{icon('bolt')}Nearly 20 years of experience</div></div></div><section class="section wrap"><div class="section-head"><div><h2>From the first wire<br>to the final fixture.</h2><p>New construction, a new fixture, or a problem to solve. We’ll help you find the right electrical service.</p></div>{textlink('Explore all services','/services/')}</div><div class="cards">{''.join(service(s) for s in SERVICES)}</div></section><section class="section work-section"><div class="wrap"><div class="section-head"><div><h2>The work speaks for itself.</h2><p>A closer look at what we’ve wired, installed, and brought to life.</p></div>{textlink('View our project gallery','/portfolio/')}</div><div class="cards">{''.join(project(PROJECTS[i]) for i in [0,7,13])}</div></div></section>{story()}{area()}<section class="section wrap"><div class="section-head"><div><h2>Notes from the job site.</h2><p>Project stories from our residential, commercial, and industrial work.</p></div>{textlink('Visit the blog','/blog/')}</div><div class="cards">{''.join(blogcard(p) for p in POSTS)}</div></section>{cta()}'''
save('/','Phoenix Electricians — The Good Guy Price','Family-owned electrical services in Phoenix. Explore real residential, commercial and industrial work. Call (623) 202-2164 for a free quote.',home)

faq='<section class="section area"><div class="wrap faq"><h2>A few things to know.</h2><details><summary>Do you offer free quotes?</summary><p>Yes. Ground-up service, fixture installation, and troubleshooting are all available with a free quote. Call us to discuss the scope of your project.</p></details><details><summary>Do you work on homes and businesses?</summary><p>Our existing projects include residential, commercial, and industrial electrical work. Explore the gallery to see examples.</p></details><details><summary>Can I speak with someone in Spanish?</summary><p>Sí. Llame al (623) 202-2164 para hablar sobre su proyecto.</p></details><details><summary>How do I get started?</summary><p>Call (623) 202-2164 or prepare your project details on our free quote page. Have your location and a short description of the work ready.</p></details></div></section>'
save('/services/','Electrical Services in Phoenix','Ground-up electrical service, fixture installation and troubleshooting from Montesinos Electric. Free project quotes in the Phoenix area.',intro('Electrical work, done right.','Three ways we can help with your next project. Every service starts with a free quote.','Services')+f'<section class="page-content wrap"><div class="cards">{"".join(service(s) for s in SERVICES)}</div></section>'+faq+cta(),'/services/')
for s in SERVICES:
    content=intro(s['name'],s['short'],f'<a href="/services/">Services</a><span>/</span>{s["name"]}')+f'''<section class="page-content wrap detail-grid">{image(s['image'],s['name'],'detail-image',eager=True)}<div class="detail-copy"><span class="quote-tag">Free quote</span><h2>Let’s talk about<br>what you need.</h2><p>{s['description']}</p><p>Examples from our existing work include:</p><ul>{''.join('<li>'+icon('check')+e(t)+'</li>' for t in s['examples'])}</ul>{button('Get a free quote','/contact/?service='+s['slug'])}<p style="margin-top:20px;font-size:12px">Prefer to talk? <a href="tel:{B['phoneLink']}">{B['phone']}</a></p></div></section>'''+cta()
    schema={'@context':'https://schema.org','@type':'Service','name':s['name'],'description':s['description'],'provider':{'@id':ORIGIN+'/#business'},'areaServed':{'@type':'City','name':'Phoenix'}}
    save('/services/'+s['slug']+'/',s['name']+' in Phoenix',s['description'],content,'/services/',schema)

gallery=intro('Real projects. Real work.','Explore electrical work for homes, businesses, and industrial spaces. Every photo is from Montesinos Electric’s existing project collection.','Our work')+f'''<section class="page-content wrap"><div class="filters" role="group" aria-label="Filter projects">{''.join(f'<button class="filter" data-filter="{c}" aria-pressed="{str(c=="All").lower()}">{c}</button>' for c in ['All','Residential','Commercial','Industrial'])}<span class="gallery-count" role="status" aria-live="polite">{len(PROJECTS)} projects</span></div><div class="gallery-grid">{''.join(project(p) for p in PROJECTS)}</div></section>'''+cta()
save('/portfolio/','Electrical Project Gallery','View real residential, commercial and industrial projects by Montesinos Electric. Filter photos and explore finished electrical work.',gallery,'/portfolio/')
save('/about/','Our Family-Owned Electrical Business',B['story'],intro('A family business.<br>A personal commitment.','Nearly 20 years of electrical experience, with honest pricing and clear communication.','Our story')+story()+f'<section class="section area"><div class="wrap detail-grid"><div><h2>The good guy price.</h2></div><div><p>At Montesinos Electric, we pride ourselves on delivering quality electrical services that meet your needs. Our dedicated team ensures your satisfaction with every project.</p><p style="margin-top:20px">From new homes to commercial equipment, our work covers the electrical installations, troubleshooting, and maintenance that keep a space working.</p><div style="margin-top:26px">{textlink("See what we’ve worked on","/portfolio/")}</div></div></div></section>'+cta(),'/about/')
save('/blog/','Project Stories & Blog','Read residential, commercial and industrial project stories from Montesinos Electric’s existing blog.',intro('From our job site<br>to your next project.','A look behind the work. Explore our original project stories and photos.','Blog')+f'<section class="page-content wrap"><div class="cards">{"".join(blogcard(p) for p in POSTS)}</div></section>'+cta(),'/blog/')
for post in POSTS:
    slug,category,title,desc=post
    photos=[p for p in PROJECTS if p['category']==category]
    featured={'Residential':PROJECTS[1],'Commercial':PROJECTS[7],'Industrial':PROJECTS[13]}[category]
    content=f'''<section class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a><span>/</span><a href="/blog/">Blog</a><span>/</span>{category}</div><div class="article-header"><div><p class="date"><time datetime="2025-10-29">October 29, 2025</time> &nbsp; · &nbsp; Montesinos Electric</p><h1>{category}<br>project stories.</h1><p>{desc}</p></div>{image(featured['image'],featured['title'],eager=True)}</div></div></section><section class="article-body"><div class="wrap"><p>{title} Take a look at the installations and electrical work in our {category.lower()} project collection.</p><div class="article-gallery">{''.join(project(p) for p in photos)}</div><div style="margin-top:40px">{textlink('Back to all project stories','/blog/')}</div></div></section>'''+cta()
    schema={'@context':'https://schema.org','@type':'BlogPosting','headline':category+' project stories','datePublished':'2025-10-29','author':{'@type':'Organization','name':B['name']},'image':ORIGIN+'/assets/'+Path(featured['image']).with_suffix('.webp').name,'publisher':{'@id':ORIGIN+'/#business'}}
    save('/post/'+slug+'/',category+' Electrical Projects',desc,content,'/blog/',schema)

contact=intro('Good work starts<br>with a conversation.','Tell us about your project. We’ll help you figure out the next step, starting with a free quote.','Contact & free quote')+f'''<section class="page-content wrap contact-layout"><aside class="contact-aside"><h2>Call your local team.</h2><p>Talk through your electrical project with Montesinos Electric.</p><div class="contact-item"><span>Call Montesinos Electric</span><a href="tel:{B['phoneLink']}">{B['phone']}</a><p>Hablamos español.</p></div><div class="contact-item"><span>Additional phone</span><a href="tel:+16025164732">{B['additionalPhone']}</a></div><div class="contact-item"><span>Service area</span><strong>Phoenix, Arizona</strong><p>Call to confirm availability for your project location.</p>{textlink('View on Google Maps',B['mapsUrl'])}</div></aside><div><form class="quote-form" id="quote-form"><h2>Prepare your free quote request.</h2><p class="form-intro">Put your project details together, then call our team. You can copy your request to share during the conversation. Online delivery is not available yet.</p><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required maxlength="120" placeholder="First and last name"></div><div class="field"><label for="phone">Phone number *</label><input id="phone" name="phone" type="tel" autocomplete="tel" required maxlength="30" placeholder="(602) 555-0123"></div><div class="field"><label for="email">Email <small>(optional)</small></label><input id="email" name="email" type="email" autocomplete="email" maxlength="200" placeholder="you@example.com"></div><div class="field"><label for="location">Project city or ZIP code *</label><input id="location" name="location" autocomplete="address-level2" required maxlength="120" placeholder="Phoenix, AZ"></div><div class="field wide"><label for="service">What can we help with? *</label><select id="service" name="service" required><option value="">Select a service</option>{''.join(f'<option value="{s["slug"]}">{s["name"]}</option>' for s in SERVICES)}<option value="other">Other electrical project</option></select></div><div class="field wide"><label for="details">Tell us about your project *</label><textarea id="details" name="details" required maxlength="5000" placeholder="What needs to be installed, built, or fixed?"></textarea></div></div><button class="button" type="submit">Prepare my quote request {icon('arrow')}</button><p class="form-note">Your details stay in this browser until you choose to share them. <a href="/privacy/">Website privacy</a></p><section class="quote-result" id="quote-result" hidden aria-labelledby="result-title"><h3 id="result-title" tabindex="-1">Your project details are ready.</h3><p>These details have not been sent. Call {B['phone']} to arrange your free quote, or copy your request to share with the team.</p><label class="sr-only" for="request-summary">Your prepared quote request</label><textarea id="request-summary" readonly></textarea><div class="result-actions">{button('Call Montesinos Electric','tel:'+B['phoneLink'])}<button type="button" class="button outline" id="copy-request">Copy request details</button></div><p id="copy-status" role="status" style="margin-top:12px"></p></section></form></div></section>'''+area()
