privacy=intro('Website privacy.','How this website handles the details you enter.','Website privacy')+f'''<section class="page-content wrap"><div class="plain-copy"><p>Last updated October 9, 2026.</p><h2>Preparing a quote request</h2><p>The quote form prepares a summary in your browser. It does not send a request, email the business, or save your details to a database. The website does not use local storage to save form entries. The form includes a name, phone number, optional email, project location, service, and project description. You choose whether to copy those details and share them with the team.</p><h2>Calling or copying your details</h2><p>Phone links open your device’s calling application. The copy button writes the prepared request to your clipboard when you select it. Your device or browser may have its own clipboard and autofill settings.</p><h2>Maps and external links</h2><p>Google Maps loads when you select “Load area map.” Google then handles that map connection under its own <a href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">privacy policy</a>. The Google Maps business listing also opens on Google’s website. Website hosting may process ordinary connection information to serve pages.</p><h2>Contact</h2><p>For questions about Montesinos Electric, call <a href="tel:{B['phoneLink']}">{B['phone']}</a>.</p></div></section>'''
save('/privacy/','Website Privacy','How the Montesinos Electric redesign handles quote preparation, copying, phone links and maps.',privacy)
access=intro('A website you can use.','If something gets in your way, we want to know.','Accessibility')+f'''<section class="page-content wrap"><div class="plain-copy"><h2>Using this website</h2><p>The website includes keyboard navigation, a skip-to-content link, labelled form fields, text descriptions for project images, visible focus indicators, and layouts that adapt to smaller screens. Project photos open in a dialog that you can close with Escape. Use the arrow keys to move between photos.</p><h2>Need help?</h2><p>Call <a href="tel:{B['phoneLink']}">{B['phone']}</a> if you need help accessing project information or discussing a quote. Hablamos español.</p><h2>Third-party maps</h2><p>The embedded Google map is provided by Google. You can also use the <a href="{B['mapsUrl']}">Google Maps business listing</a> or call us to discuss your project location.</p></div></section>'''
save('/accessibility/','Accessibility','Keyboard navigation, accessible project viewing and contact help on the Montesinos Electric website.',access)

save('/404/','Page Not Found','Find Montesinos Electric services, project photos and free quotes.',f'<section class="not-found wrap"><h1>Let’s get you<br>back on track.</h1><p>That page could not be found. Explore our services or contact the team.</p>{button("Back to the homepage","/")}</section>')
shutil.copy2(DIST/'404'/'index.html',DIST/'404.html')
# Preserve entry points visitors may follow from the original website.
aliases={'/book-online/':'/services/','/booking-form/':'/contact/','/blank/':'/privacy/','/blank-1/':'/accessibility/'}
for s in SERVICES:
    aliases['/service-page/'+s['slug']+'/']='/services/'+s['slug']+'/'
    aliases['/booking-calendar/'+s['slug']+'/']='/contact/?service='+s['slug']
for path,target in aliases.items():
    f=DIST/path.strip('/')/'index.html';f.parent.mkdir(parents=True,exist_ok=True)
    f.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0; url={target}"><title>Montesinos Electric</title></head><body><p><a href="{target}">Continue to Montesinos Electric</a></p></body></html>',encoding='utf-8')
(DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n# Private redesign preview. Enable indexing after production launch.\n',encoding='utf-8')
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN+path}</loc></url>' for path in PAGES if path!='/404/')+'</urlset>',encoding='utf-8')
manifest=json.loads((ROOT/'.openai'/'hosting.json').read_text(encoding='utf-8'));manifest['static']={'directory':'dist'}
(ROOT/'.openai'/'hosting.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
(ROOT/'page-inventory.json').write_text(json.dumps(PAGES,indent=2),encoding='utf-8')
print(f'Generated {len(PAGES)} pages, {len(aliases)} original URL redirects, and {len(PROJECTS)} project entries.')
